170	 * and event history. The constructor accepts a `cwd` parameter that defaults
171	 * to `process.cwd()`. It does NOT validate that `.agentrack/` exists at
172	 * construction time — resolution happens on each method call.
173	 *
174	 * @example
175	 * ```typescript
176	 * import { Tracker } from "agentrack";
177	 *
178	 * const tracker = new Tracker("/path/to/project");
179	 * await tracker.init();
180	 * const { id } = await tracker.create({ title: "My first issue" });
181	 * ```
182	 */
183	export class Tracker {
184	  private cwd: string;
185	
186	  /**
187	   * Create a new Tracker instance.
188	   *
189	   * @param cwd - Working directory to resolve `.agentrack/` from. Defaults to `process.cwd()`.
190	   */
191	  constructor(cwd?: string) {
192	    this.cwd = cwd ?? process.cwd();
193	  }
194	
195	  /**
196	   * Initialize a new `.agentrack/` directory in `cwd`.
197	   *
198	   * Creates the directory structure with all initial files:
199	   * `config.json`, `index.json`, `dependencies.json`, `users.json`,
200	   * and an empty `issues/` subdirectory.
201	   *
202	   * @returns `{ result: "OK", path }` on success, or `{ result: "ALREADY_INITIALIZED", path }` if already exists
203	   *
204	   * @example
205	   * ```typescript
206	   * const result = await tracker.init();
207	   * if (result.result === "OK") console.log("Created at", result.path);
208	   * ```
209	   */
210	  async init(): Promise<InitResult> {
211	    const trackerDir = join(this.cwd, AGENTACK_DIR);
212	
213	    if (existsSync(trackerDir)) {
214	      return { result: "ALREADY_INITIALIZED", path: resolve(trackerDir) };
215	    }
216	
217	    mkdirSync(trackerDir, { recursive: true });
218	    mkdirSync(join(trackerDir, "issues"), { recursive: true });
219	
220	    await atomicWriteJSON(join(trackerDir, "config.json"), DEFAULT_CONFIG);
221	    await atomicWriteJSON(join(trackerDir, "index.json"), DEFAULT_INDEX);
222	    await atomicWriteJSON(join(trackerDir, "dependencies.json"), DEFAULT_DEPENDENCIES);
223	    await atomicWriteJSON(join(trackerDir, "users.json"), DEFAULT_USERS);
224	
225	    return { result: "OK", path: resolve(trackerDir) };
226	  }
227	
228	  /**
229	   * Create a new issue.
230	   *
231	   * Generates a unique ID, creates the issue file with creation + update events,
232	   * and inserts an entry into the sorted index. Validates parent constraints if
233	   * `parentId` is provided.
234	   *
235	   * @param params - Creation parameters
236	   * @param params.title - The issue title (required)
237	   * @param params.description - Optional description, defaults to ""
238	   * @param params.status - Initial status, defaults to "idea"
239	   * @param params.priority - Priority 1-5, defaults to 3
240	   * @param params.assignee - Optional assignee, defaults to null
241	   * @param params.tags - Optional tags, defaults to []
242	   * @param params.parentId - Optional parent issue ID for hierarchy
243	   * @param params.author - Override author (resolved by auth layer if not provided)
244	   * @returns `{ id }` on success, or a AgentrackError on auth failure
245	   * @throws {AgentrackError} NOT_INITIALIZED if no `.agentrack/` directory
246	   * @throws {AgentrackError} NOT_FOUND if parentId doesn't exist in index
247	   * @throws {AgentrackError} HIERARCHY_CONSTRAINT if parent is closed
248	   *
249	   * @example
250	   * ```typescript
251	   * const { id } = await tracker.create({
252	   *   title: "Bug fix",
253	   *   priority: 1,
254	   *   tags: ["bug", "urgent"],
255	   * });
256	   * ```
257	   */
258	  async create(params: CreateParams): Promise<CreateResult> {
259	    const trackerDir = resolveTrackerDir(this.cwd);
260	    if (!trackerDir) {
261	      throw new AgentrackError(
262	        ErrorCodes.NOT_INITIALIZED.result,
263	        "No .agentrack/ directory found. Run `agt init` first.",
264	        ErrorCodes.NOT_INITIALIZED.exitCode,
265	      );
266	    }
267	
268	    const config = await readJSON<ConfigFile>(join(trackerDir, "config.json"));
269	    const users = await readJSON<UsersFile>(join(trackerDir, "users.json"));
270	    const authResult = resolveAuthor({ config, users, requiresWrite: true });
271	    if (authResult instanceof AgentrackError) return authResult;
272	    const author = params.author ?? authResult.author;
273	
274	    const id = generateId();
275	    const issuePath = params.path ?? `issues/${id}.json`;
276	    const now = new Date().toISOString();
277	
278	    const title = params.title;
279	    const description = params.description ?? "";
280	    const status: IssueStatus = params.status ?? "idea";
281	    const priority = params.priority ?? 3;
282	    const assignee = params.assignee ?? null;
283	    const parentId = params.parentId ?? null;
284	    const tags = params.tags ?? [];
285	
286	    // Read index early for parent validation
287	    const index = await readIndex(trackerDir);
288	
289	    // Validate parent exists and is not closed
290	    if (parentId) {
291	      const parentEntry = findEntry(index, parentId);
292	      if (!parentEntry) {
293	        throw new AgentrackError(
294	          ErrorCodes.NOT_FOUND.result,
295	          `Parent issue \`${parentId}\` not found in index.`,
296	          ErrorCodes.NOT_FOUND.exitCode,
297	        );
298	      }
299	      const validationError = validateNewChild(parentEntry);
300	      if (validationError) {
301	        throw new AgentrackError(
302	          ErrorCodes.HIERARCHY_CONSTRAINT.result,
303	          validationError,
304	          ErrorCodes.HIERARCHY_CONSTRAINT.exitCode,
305	        );
306	      }
307	    }
308	
309	    // Build update content with only non-default values
310	    const updateContent: Partial<
311	      Pick<
312	        IssueProperties,
313	        "title" | "description" | "status" | "assignee" | "tags" | "priority" | "parentId"
314	      >
315	    > & { title: string } = { title };
316	    if (description) updateContent.description = description;
317	    if (status !== "idea") updateContent.status = status;
318	    if (priority !== 3) updateContent.priority = priority;
319	    if (assignee !== null) updateContent.assignee = assignee;
320	    if (parentId !== null) updateContent.parentId = parentId;
321	    if (tags.length > 0) updateContent.tags = tags;
322	
323	    // Create issue file with two events: creation + update
324	    const creationEvent = { type: "creation" as const, timestamp: now, author };
325	    const updateEvent = {
326	      type: "update" as const,
327	      timestamp: now,
328	      author,
329	      content: updateContent,
330	    };
331	
332	    const issueFilePath = join(trackerDir, issuePath);
333	    await atomicWriteJSON(issueFilePath, [creationEvent, updateEvent]);
334	
335	    // Build index entry and insert into index
336	    const entry: IndexEntry = {
337	      id,
338	      title,
339	      path: issuePath,
340	      status,
341	      assignee,
342	      parentId,
343	      tags,
344	      priority,
345	    };
346	
347	    const updatedIndex = insertEntry(index, entry);
348	    await writeIndex(trackerDir, updatedIndex);
349	
350	    return { id };
351	  }
352	
353	  /**
354	   * List issues from the index with optional filters.
355	   *
356	   * Returns entries sorted by: priority ASC → impact score DESC → id ASC.
357	   * Impact score is the count of active issues this issue blocks.
358	   *
359	   * @param params - Optional filter parameters
360	   * @param params.status - Filter by status; "open" = all non-closed, "closed" = closed only
361	   * @param params.assignee - Filter by assignee name
362	   * @param params.tags - AND filter — issue must have ALL specified tags
363	   * @param params.parentId - Filter by parent ID; null = top-level issues only
364	   * @returns Array of index entries matching the filters
365	   * @throws {AgentrackError} NOT_INITIALIZED if no `.agentrack/` directory
366	   * @throws {AgentrackError} TOKEN_REQUIRED if auth mode is strict and no token provided
367	   *
368	   * @example
369	   * ```typescript
370	   * const openUrgent = await tracker.list({
371	   *   status: "open",
372	   *   tags: ["urgent"],
373	   *   parentId: null,
374	   * });
375	   * ```
376	   */
377	  async list(params?: ListParams): Promise<ListResult> {
378	    const trackerDir = resolveTrackerDir(this.cwd);
379	    if (!trackerDir) {
380	      throw new AgentrackError(
381	        ErrorCodes.NOT_INITIALIZED.result,
382	        "No .agentrack/ directory found. Run `agt init` first.",
383	        ErrorCodes.NOT_INITIALIZED.exitCode,
384	      );
385	    }
386	
387	    const config = await readJSON<ConfigFile>(join(trackerDir, "config.json"));
388	    const users = await readJSON<UsersFile>(join(trackerDir, "users.json"));
389	    const authResult = resolveAuthor({ config, users, requiresWrite: false });
390	    if (authResult instanceof AgentrackError) {
391	      throw authResult;
392	    }
393	
394	    const index = await readIndex(trackerDir);
395	
396	    // Determine source arrays based on params.status
397	    let entries: IndexEntry[];
398	    if (params?.status === "closed") {
399	      entries = index.closed;
400	    } else if (params?.status === "open") {
401	      entries = index.open;
402	    } else if (params?.status) {
403	      entries = index.open;
404	    } else {
405	      entries = [...index.open, ...index.closed];
406	    }
407	
408	    // Filter in memory
409	    let filtered = entries;
410	
411	    if (params?.status && params.status !== "open" && params.status !== "closed") {
412	      filtered = filtered.filter((e) => e.status === params.status);
413	    }
414	
415	    if (params?.assignee) {
416	      filtered = filtered.filter((e) => e.assignee === params.assignee);
417	    }
418	
419	    if (params?.tags && params.tags.length > 0) {
420	      filtered = filtered.filter((e) => params.tags?.every((tag) => e.tags.includes(tag)));
421	    }
422	
423	    if (params?.parentId !== undefined) {
424	      if (params.parentId === null) {
425	        filtered = filtered.filter((e) => e.parentId === null);
426	      } else {
427	        filtered = filtered.filter((e) => e.parentId === params.parentId);
428	      }
429	    }
430	
431	    // Read dependencies once for impact score
432	    let deps: DependenciesFile | null = null;
433	
434	    // Sort: priority ASC → impact DESC → id ASC
435	    filtered.sort((a, b) => {
436	      if (a.priority !== b.priority) return a.priority - b.priority;
437	      // Lazy-load deps only once for sorting
438	      if (!deps) {
439	        deps = readDependenciesSync(trackerDir);
440	      }
441	      const impactA = getImpactScore(deps, a.id);
442	      const impactB = getImpactScore(deps, b.id);
443	      if (impactA !== impactB) return impactB - impactA;
444	      return a.id.localeCompare(b.id);
445	    });
446	
447	    return filtered;
448	  }
449	
450	  /**
451	   * View a single issue's full computed state.
452	   *
453	   * Replays all events from the issue file to produce the current computed state,
454	   * including all property values and timestamps.
455	   *
456	   * @param id - The issue ID to look up
457	   * @returns The full computed issue state, or a AgentrackError
458	   * @throws {AgentrackError} NOT_INITIALIZED if no `.agentrack/` directory
459	   * @throws {AgentrackError} NOT_FOUND if issue ID is not in the index
460	   * @throws {AgentrackError} ISSUE_MISSING if index entry exists but file is missing
461	   *
462	   * @example
463	   * ```typescript
464	   * const issue = await tracker.view("abc123def4");
465	   * if ("title" in issue) console.log(issue.title, issue.status);
466	   * ```
467	   */
468	  async view(id: IssueId): Promise<ViewResult> {
469	    const trackerDir = resolveTrackerDir(this.cwd);
470	    if (!trackerDir) {
471	      throw new AgentrackError(
