508	  /**
509	   * Get the recommended next issue to work on for a given user.
510	   *
511	   * Filters open issues by assignee and active status, excludes blocked issues,
512	   * then sorts by priority ASC → impact DESC → id ASC and returns the top issue.
513	   *
514	   * @param assignee - The assignee name to filter by (case-sensitive)
515	   * @returns The recommended ComputedIssue, or `{ result: "NO_ISSUES_AVAILABLE" }`
516	   * @throws {AgentrackError} NOT_INITIALIZED if no `.agentrack/` directory
517	   * @throws {AgentrackError} TOKEN_REQUIRED if auth mode is strict and no token provided
518	   *
519	   * @example
520	   * ```typescript
521	   * const result = await tracker.next("alice");
522	   * if ("title" in result) console.log("Work on:", result.title);
523	   * else console.log("No issues available:", result.message);
524	   * ```
525	   */
526	  async next(assignee: string): Promise<NextResult> {
527	    const trackerDir = resolveTrackerDir(this.cwd);
528	    if (!trackerDir) {
529	      throw new AgentrackError(
530	        ErrorCodes.NOT_INITIALIZED.result,
531	        "No .agentrack/ directory found. Run `agt init` first.",
532	        ErrorCodes.NOT_INITIALIZED.exitCode,
533	      );
534	    }
535	
536	    const config = await readJSON<ConfigFile>(join(trackerDir, "config.json"));
537	    const users = await readJSON<UsersFile>(join(trackerDir, "users.json"));
538	    const authResult = resolveAuthor({ config, users, requiresWrite: false });
539	    if (authResult instanceof AgentrackError) {
540	      throw authResult;
541	    }
542	
543	    const index = await readIndex(trackerDir);
544	
545	    // Filter to open issues assigned to this user that are todo (ready to start)
546	    let candidates = index.open.filter(
547	      (e) => e.assignee === assignee && e.status === "todo",
548	    );
549	
550	    // Read dependencies for blockage filtering and impact scoring
551	    const deps = readDependenciesSync(trackerDir);
552	
553	    // Filter out issues with any active blockages
554	    candidates = candidates.filter((e) => {
555	      const blockedBy = deps.blockedBy[e.id] ?? [];
556	      return !blockedBy.some((b) => b.status === "active");
557	    });
558	
559	    // If no candidates remain, return no issues available
560	    if (candidates.length === 0) {
561	      return {
562	        result: "NO_ISSUES_AVAILABLE",
563	        message: `No todo issues found for user '${assignee}'.`,
564	      };
565	    }
566	
567	    // Sort: priority ASC → impact DESC → id ASC
568	    candidates.sort((a, b) => {
569	      if (a.priority !== b.priority) return a.priority - b.priority;
570	      const impactA = getImpactScore(deps, a.id);
571	      const impactB = getImpactScore(deps, b.id);
572	      if (impactA !== impactB) return impactB - impactA;
573	      return a.id.localeCompare(b.id);
574	    });
575	
576	    // Take top issue, replay events, return computed state
577	    const topEntry = candidates[0]!;
578	    const issueFilePath = join(trackerDir, topEntry.path);
579	    if (!existsSync(issueFilePath)) {
580	      throw new AgentrackError(
581	        ErrorCodes.ISSUE_MISSING.result,
582	        `Issue file for \`${topEntry.id}\` is missing.`,
583	        ErrorCodes.ISSUE_MISSING.exitCode,
584	      );
585	    }
586	
587	    const events = await replayEvents(issueFilePath);
588	    return computeState(events, topEntry.id);
589	  }
