1225	   * @param blockedId - The issue that is blocked
1226	   * @param params - Blockage parameters
1227	   * @param params.blockerIds - Array of blocker issue IDs
1228	   * @param params.author - Override author (resolved by auth layer if not provided)
1229	   * @returns `{ result: "OK" }` on success, or a AgentrackError
1230	   * @throws {AgentrackError} NOT_INITIALIZED if no `.agentrack/` directory
1231	   * @throws {AgentrackError} NOT_FOUND if blockedId or any blockerId is not in the index
1232	   * @throws {AgentrackError} BLOCKAGE_CYCLE if adding the blockage would create a cycle
1233	   *
1234	   * @example
1235	   * ```typescript
1236	   * await tracker.blockagesAdd("blocked001", {
1237	   *   blockerIds: ["blocker001", "blocker002"],
1238	   * });
1239	   * ```
1240	   */
1241	  async blockagesAdd(blockedId: IssueId, params: BlockagesAddParams): Promise<BlockagesAddResult> {
1242	    const trackerDir = resolveTrackerDir(this.cwd);
1243	    if (!trackerDir) {
1244	      throw new AgentrackError(
1245	        ErrorCodes.NOT_INITIALIZED.result,
1246	        "No .agentrack/ directory found. Run `agt init` first.",
1247	        ErrorCodes.NOT_INITIALIZED.exitCode,
1248	      );
1249	    }
1250	
1251	    const config = await readJSON<ConfigFile>(join(trackerDir, "config.json"));
1252	    const users = await readJSON<UsersFile>(join(trackerDir, "users.json"));
1253	    const authResult = resolveAuthor({ config, users, requiresWrite: true });
1254	    if (authResult instanceof AgentrackError) return authResult;
1255	    const author = params.author ?? authResult.author;
1256	
1257	    const index = await readIndex(trackerDir);
1258	
1259	    // Validate blockedId exists
1260	    if (!findEntry(index, blockedId)) {
1261	      throw new AgentrackError(
1262	        ErrorCodes.NOT_FOUND.result,
1263	        `Issue \`${blockedId}\` not found in index.`,
1264	        ErrorCodes.NOT_FOUND.exitCode,
1265	      );
1266	    }
1267	
1268	    // Validate all blockerIds exist
1269	    for (const blockerId of params.blockerIds) {
1270	      if (!findEntry(index, blockerId)) {
1271	        throw new AgentrackError(
1272	          ErrorCodes.NOT_FOUND.result,
1273	          `Issue \`${blockerId}\` not found in index.`,
1274	          ErrorCodes.NOT_FOUND.exitCode,
1275	        );
1276	      }
1277	    }
1278	
1279	    const deps = await readDependencies(trackerDir);
1280	
1281	    // Projected state: deep clone and validate cycle for each blocker
1282	    let projected = {
1283	      blockedBy: { ...deps.blockedBy },
1284	      blocks: { ...deps.blocks },
1285	    };
1286	
1287	    for (const blockerId of params.blockerIds) {
1288	      projected = addBlockage(projected, blockedId, blockerId);
1289	      if (detectCycle(projected, blockedId, blockerId)) {
1290	        throw new AgentrackError(
1291	          ErrorCodes.BLOCKAGE_CYCLE.result,
1292	          `Blockage would create a cycle: \`${blockedId}\` → ... → \`${blockerId}\`.`,
1293	          ErrorCodes.BLOCKAGE_CYCLE.exitCode,
1294	        );
1295	      }
1296	    }
1297	
1298	    // All passed — write projected state
1299	    await writeDependencies(trackerDir, projected);
1300	
1301	    // Append events to blockedId's issue file
1302	    const blockedEntry = findEntry(index, blockedId)!;
1303	    const issueFilePath = join(trackerDir, blockedEntry.path);
1304	
1305	    for (const blockerId of params.blockerIds) {
1306	      const now = new Date().toISOString();
1307	      const event: Event = {
1308	        type: "blockage-added",
1309	        timestamp: now,
1310	        author,
1311	        content: { blockerId },
1312	      };
1313	      await appendEvent(issueFilePath, event);
1314	    }
1315	
1316	    return { result: "OK" };
1317	  }
