1	import { existsSync, readFileSync, writeFileSync } from "node:fs";
2	import { resolve } from "node:path";
3	import { AgentrackError } from "../../core/errors";
4	import { Tracker } from "../../core/tracker";
5	import {
6	  DEFAULT_BRANCH,
7	  commitGitignoreChange,
8	  commitWorktreeData,
9	  initWorktree,
10	  isWorktreeInitialized,
11	} from "../../core/worktree";
12	import { normalizeBranchName, writeBranchPointer, defaultWorktreeOptions } from "../../core/branch-config";
13	import type { WorktreeOptions } from "../../core/branch-config";
14	import { writeStderr, writeStdout } from "../output";
15	
16	/**
17	 * Handler for the `agt init` command.
18	 *
19	 * When inside a git repo, sets up a git worktree for agentrack data
20	 * (orphan branch, default _agentrack). When not inside a git repo, falls back
21	 * to classic Tracker.init() which creates a plain directory.
22	 *
23	 * Accepts optional `--branch <name>` flag to customize the branch/directory names.
24	 */
25	export async function initAction(options?: { branch?: string }): Promise<void> {
26	  try {
27	    const cwd = process.cwd();
28	
29	    // Resolve branch/directory from flag or defaults
30	    let opts: WorktreeOptions;
31	    if (options?.branch) {
32	      opts = normalizeBranchName(options.branch);
33	    } else {
34	      opts = defaultWorktreeOptions();
35	    }
36	
37	    // Try worktree-based init (only works in git repos)
38	    try {
39	      // Check if already initialized as a worktree
40	      if (isWorktreeInitialized(cwd, opts)) {
41	        writeStdout({
42	          result: "ALREADY_INITIALIZED",
43	          path: resolve(cwd, opts.dir),
44	        });
45	        process.exit(0);
46	      }
47	
48	      // Perform worktree setup (checks preconditions, detects scenario, mounts)
49	      const worktreeResult = initWorktree(cwd, opts);
50	
51	      // Run tracker.init() - will return ALREADY_INITIALIZED since worktree
52	      // already contains the initial data files (from plumbing or remote).
53	      const tracker = new Tracker(cwd);
54	      await tracker.init();
55	
56	      // Write branch to config.json inside the worktree
57	      writeBranchToConfig(cwd, opts);
58	
59	      // Write pointer file at repo root for discovery
60	      if (opts.branch !== DEFAULT_BRANCH) {
61	        writeBranchPointer(cwd, opts.branch);
62	      }
63	
64	      // Auto-commit gitignore change and initialized data (fresh scenario)
65	      if (worktreeResult.scenario === "fresh") {
66	        // Also commit the pointer file if present
67	        commitGitignoreChange(cwd, opts.dir);
68	        commitWorktreeData(cwd, `init agentrack data`, opts);
69	      }
70	
71	      writeStdout({
72	        result: "OK",
73	        scenario: worktreeResult.scenario,
74	        path: worktreeResult.path,
75	      });
76	      process.exit(0);
77	    } catch (worktreeErr) {
78	      // If not a git repo, fall back to classic directory-based init
