import { existsSync, readFileSync, writeFileSync } from "node:fs";
import { resolve } from "node:path";
import { AgentrackError } from "../../core/errors";
import { Tracker } from "../../core/tracker";
import {
  DEFAULT_BRANCH,
  commitGitignoreChange,
  commitWorktreeData,
  initWorktree,
  isWorktreeInitialized,
} from "../../core/worktree";
import { normalizeBranchName, writeBranchPointer, defaultWorktreeOptions } from "../../core/branch-config";
import type { WorktreeOptions } from "../../core/branch-config";
import { writeStderr, writeStdout } from "../output";

/**
 * Handler for the `agt init` command.
 *
 * When inside a git repo, sets up a git worktree for agentrack data
 * (orphan branch, default _agentrack). When not inside a git repo, falls back
 * to classic Tracker.init() which creates a plain directory.
 *
 * Accepts optional `--branch <name>` flag to customize the branch/directory names.
 */
export async function initAction(options?: { branch?: string }): Promise<void> {
  try {
    const cwd = process.cwd();

    // Resolve branch/directory from flag or defaults
    let opts: WorktreeOptions;
    if (options?.branch) {
      opts = normalizeBranchName(options.branch);
    } else {
      opts = defaultWorktreeOptions();
    }

    // Try worktree-based init (only works in git repos)
    try {
      // Check if already initialized as a worktree
      if (isWorktreeInitialized(cwd, opts)) {
        writeStdout({
          result: "ALREADY_INITIALIZED",
          path: resolve(cwd, opts.dir),
        });
        process.exit(0);
      }

      // Perform worktree setup (checks preconditions, detects scenario, mounts)
      const worktreeResult = initWorktree(cwd, opts);

      // Run tracker.init() - will return ALREADY_INITIALIZED since worktree
      // already contains the initial data files (from plumbing or remote).
      const tracker = new Tracker(cwd);
      await tracker.init();

      // Write branch to config.json inside the worktree
      writeBranchToConfig(cwd, opts);

      // Write pointer file at repo root for discovery
      if (opts.branch !== DEFAULT_BRANCH) {
        writeBranchPointer(cwd, opts.branch);
      }

      // Auto-commit gitignore change and initialized data (fresh scenario)
      if (worktreeResult.scenario === "fresh") {
        // Also commit the pointer file if present
        commitGitignoreChange(cwd, opts.dir);
        commitWorktreeData(cwd, `init agentrack data`, opts);
      }

      writeStdout({
        result: "OK",
        scenario: worktreeResult.scenario,
        path: worktreeResult.path,
      });
      process.exit(0);
    } catch (worktreeErr) {
      // If not a git repo, fall back to classic directory-based init
      if (
        worktreeErr instanceof AgentrackError &&
        worktreeErr.result === "NOT_A_GIT_REPO"
      ) {
        const tracker = new Tracker();
        const result = await tracker.init();
        writeStdout(result);
        process.exit(0);
      }
      throw worktreeErr;
    }
  } catch (err) {
    if (err instanceof AgentrackError) {
      writeStderr({ result: err.result, message: err.message });
      process.exit(err.exitCode);
    }
    // Unexpected errors
    writeStderr({ result: "INTERNAL_ERROR", message: (err as Error).message });
    process.exit(1);
  }
}

/**
 * Write the branch name into config.json inside the worktree.
 */
function writeBranchToConfig(cwd: string, opts: WorktreeOptions): void {
  const configPath = resolve(cwd, opts.dir, "config.json");
  if (!existsSync(configPath)) return;

  try {
    const content = readFileSync(configPath, "utf-8");
    const config = JSON.parse(content) as Record<string, unknown>;
    config["branch"] = opts.branch;
    writeFileSync(configPath, JSON.stringify(config, null, 2) + "\n", "utf-8");
  } catch {
    // Non-critical — config update is best-effort
  }
}

/**
 * Typed error class for all agentrack operations.
 * Each error has a result code, human-readable message, and CLI exit code.
 */
export class AgentrackError extends Error {
  /**
   * @param result - Machine-readable error code (e.g. "NOT_FOUND")
   * @param message - Human-readable error description
   * @param exitCode - CLI exit code associated with this error
   */
  constructor(
    public readonly result: string,
    public override readonly message: string,
    public readonly exitCode: number,
  ) {
    super(message);
    this.name = "AgentrackError";
  }
}

/**
 * Error codes with their associated CLI exit codes.
 * Each code maps to a unique exit code for programmatic error handling.
 */
export const ErrorCodes = {
  /** No `.agentrack/` directory found in cwd. */
  NOT_INITIALIZED: { result: "NOT_INITIALIZED", exitCode: 1 },
  /** `.agentrack/` directory already exists. */
  ALREADY_INITIALIZED: { result: "ALREADY_INITIALIZED", exitCode: 0 },
  /** Authentication token is required but not provided. */
  TOKEN_REQUIRED: { result: "TOKEN_REQUIRED", exitCode: 2 },
  /** The provided authentication token is invalid. */
  INVALID_TOKEN: { result: "INVALID_TOKEN", exitCode: 3 },
  /** No default user configured for unauthenticated access. */
  DEFAULT_USER_MISSING: { result: "DEFAULT_USER_MISSING", exitCode: 4 },
  /** Requested issue or resource not found. */
  NOT_FOUND: { result: "NOT_FOUND", exitCode: 5 },
  /** Issue exists in index but file is missing on disk. */
  ISSUE_MISSING: { result: "ISSUE_MISSING", exitCode: 6 },
  /** Requested comment not found on the issue. */
  COMMENT_NOT_FOUND: { result: "COMMENT_NOT_FOUND", exitCode: 7 },
  /** User with the same name already exists. */
  USER_ALREADY_EXISTS: { result: "USER_ALREADY_EXISTS", exitCode: 8 },
  /** Requested user not found. */
  USER_NOT_FOUND: { result: "USER_NOT_FOUND", exitCode: 9 },
  /** Invalid parameters provided to an operation. */
  INVALID_PARAMS: { result: "INVALID_PARAMS", exitCode: 10 },
  /** Adding blockage would create a dependency cycle. */
  BLOCKAGE_CYCLE: { result: "BLOCKAGE_CYCLE", exitCode: 11 },
  /** Hierarchy constraint violated (e.g. adding child to closed parent). */
  HIERARCHY_CONSTRAINT: { result: "HIERARCHY_CONSTRAINT", exitCode: 12 },
  /** Not inside a git repository. */
  NOT_A_GIT_REPO: { result: "NOT_A_GIT_REPO", exitCode: 13 },
  /** .agentrack/ exists but is not a git worktree (legacy directory). */
  MIGRATION_REQUIRED: { result: "MIGRATION_REQUIRED", exitCode: 14 },
  /** Invalid state for the requested operation. */
  INVALID_STATE: { result: "INVALID_STATE", exitCode: 15 },
  /** git push failed. */
  PUSH_FAILED: { result: "PUSH_FAILED", exitCode: 16 },
  /** git pull failed. */
  PULL_FAILED: { result: "PULL_FAILED", exitCode: 17 },
  /** Invalid branch name provided to --branch flag. */
  INVALID_BRANCH_NAME: { result: "INVALID_BRANCH_NAME", exitCode: 18 },
  /** Branch already exists but does not contain agentrack data. */
  BRANCH_CONFLICT: { result: "BRANCH_CONFLICT", exitCode: 19 },
} as const;

import { Command } from "commander";
import {
  blockagesAddAction,
  blockagesDeleteAction,
  blockagesListAction,
  blockagesResolveAction,
} from "./commands/blockages";
import {
  commentsAddAction,
  commentsDeleteAction,
  commentsListAction,
  commentsUpdateAction,
} from "./commands/comments";
import { createAction } from "./commands/create";
import { historyAction } from "./commands/history";
import { initAction } from "./commands/init";
import { listAction } from "./commands/list";
import { nextAction } from "./commands/next";
import { pullAction } from "./commands/pull";
import { pushAction } from "./commands/push";
import { updateAction } from "./commands/update";
import {
  usersListAction,
  usersRegenerateAction,
  usersRegisterAction,
  usersRevokeAction,
} from "./commands/users";
import { viewAction } from "./commands/view";

/**
 * Create and configure the Commander program.
 */
export function createProgram(): Command {
  const program = new Command();

  program
    .name("agt")
    .description("Issue tracker designed for AI agents — file-backed, event-sourced, git-friendly")
    .version("0.1.0");

  // ─── init ─────────────────────────────────────────────────────────
  program
    .command("init")
    .description("Initialize a new .agentrack/ directory")
    .option("--branch <name>", "Branch name for agentrack data (default: _agentrack)")
    .action(initAction);

  // ─── create ───────────────────────────────────────────────────────
  program
    .command("create <title>")
    .description("Create a new issue")
    .option("--description <string>", "Issue description")
    .option("--assignee <string>", "Assignee name")
    .option("--tags <comma-separated>", "Comma-separated tags")
    .option("--status <status>", 'Issue status (default: "idea")')
    .option("--priority <number>", "Priority 1-5 (default: 3)")
    .option("--parentId <id>", "Parent issue ID")
    .option("--path <string>", "Custom file path for the issue")
    .action(createAction);

  // ─── list ─────────────────────────────────────────────────────────
  program
    .command("list")
    .description("List issues")
    .option(
      "--status <status>",
      'Filter by status (use "open" for non-closed, "closed" for closed)',
    )
    .option("--assignee <string>", "Filter by assignee")
    .option("--tags <comma-separated>", "Comma-separated tags (AND filter)")
    .option("--parentId <id>", 'Filter by parent ID (use "null" for top-level)')
    .action(listAction);

  // ─── next ──────────────────────────────────────────────────────────
  program
    .command("next <userName>")
    .description("Get the recommended next issue to work on for a user")
    .action(nextAction);

  // ─── push ──────────────────────────────────────────────────────────
  program
    .command("push")
    .description("Sync agentrack data to remote")
    .option("--message <string>", "Override auto-generated commit message")
    .action(pushAction);

  // ─── pull ──────────────────────────────────────────────────────────
  program
    .command("pull")
    .description("Sync agentrack data from remote")
    .action(pullAction);

  // ─── view ─────────────────────────────────────────────────────────
  program
    .command("view <issueId>")
    .description("View an issue's full computed state")
    .action(viewAction);

  // ─── update ───────────────────────────────────────────────────────
  program
    .command("update <issueId>")
    .description("Update an existing issue")
    .option("--title <string>", "New title")
    .option("--description <string>", "New description")
    .option("--status <status>", "New status")
    .option("--assignee <string>", "New assignee")
    .option("--tags <comma-separated>", "New tags (replaces existing)")
    .option("--priority <number>", "New priority (1-5)")
    .option("--parentId <id>", 'New parent ID (use "null" to detach)')
    .action(updateAction);

  // ─── history ──────────────────────────────────────────────────────
  program
    .command("history <issueId>")
    .description("View an issue's raw event history")
    .action(historyAction);

  // ─── comments ─────────────────────────────────────────────────────
  const commentsCmd = program.command("comments").description("Manage comments on issues");

  commentsCmd
    .command("add <issueId>")
    .description("Add a comment to an issue")
    .requiredOption("--content <content>", "Comment content")
    .action(commentsAddAction);

  commentsCmd
    .command("update <issueId> <commentId>")
    .description("Update an existing comment")
    .requiredOption("--content <content>", "New comment content")
    .action(commentsUpdateAction);

  commentsCmd
    .command("delete <issueId> <commentId>")
    .description("Delete a comment")
    .action(commentsDeleteAction);

  commentsCmd
    .command("list <issueId>")
    .description("List comments on an issue")
    .action(commentsListAction);

  // ─── users ────────────────────────────────────────────────────────
  const usersCmd = program.command("users").description("Manage users");

  usersCmd
    .command("register <name>")
    .description("Register a new user")
    .action(usersRegisterAction);

  usersCmd.command("list").description("List registered users").action(usersListAction);

  usersCmd.command("revoke <name>").description("Revoke (remove) a user").action(usersRevokeAction);

  usersCmd
    .command("regenerate <name>")
    .description("Regenerate a user's token (self-service only)")
    .action(usersRegenerateAction);

  // ─── blockages ─────────────────────────────────────────────────────
  const blockagesCmd = program.command("blockages").description("Manage issue blockages");

  blockagesCmd
    .command("add <blockedId>")
    .description("Add blockage dependencies to an issue")
    .requiredOption("--by <ids...>", "Blocker issue IDs")
    .action(blockagesAddAction);

  blockagesCmd
    .command("resolve <blockedId>")
    .description("Resolve blockage dependencies")
    .requiredOption("--by <ids...>", "Blocker issue IDs to resolve")
    .action(blockagesResolveAction);

  blockagesCmd
    .command("delete <blockedId>")
    .description("Delete blockage dependencies")
    .requiredOption("--by <ids...>", "Blocker issue IDs to delete")
    .action(blockagesDeleteAction);

  blockagesCmd
    .command("list <issueId>")
    .description("List blockage info for an issue")
    .action(blockagesListAction);

  return program;
}

